CREATE TYPE pgenum_22.shell;
CREATE DOMAIN pgenum_22.wrapped AS pgenum_22.mood;
CREATE TYPE pgenum_22.private_guard AS ENUM ('private_catalog_guard_label');
CREATE TABLE pgenum_22.keep(id integer);
INSERT INTO pgenum_22.keep VALUES (7);
CREATE SEQUENCE pgenum_22.guard START 7;
CREATE TABLE pgenum_22.receipt AS SELECT t.oid,t.typname,t.typtype,t.typisdefined,t.typarray,array(SELECT enumlabel::text FROM pg_enum e WHERE e.enumtypid=t.oid ORDER BY e.enumsortorder) AS labels FROM pg_type t WHERE t.typnamespace='pgenum_22'::regnamespace AND t.typname NOT IN ('receipt','_receipt')

